<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import GraphView from '../components/GraphView.vue';import {create} from '../api/datasets';import {useAsync} from '../hooks/useAsync';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const selected=ref(''),name=ref(''),source=ref('transfer_network.json'),nodesText=ref('[{"node_id":"S","label":"模拟源站"},{"node_id":"T","label":"模拟汇站"}]'),arcsText=ref('[]');const ds=computed(()=>props.data.datasets.find(d=>d.id===selected.value)||props.data.datasets[0]);const arcs=computed(()=>props.data.arcs.filter(a=>a.dataset_id===ds.value?.id));const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,source:source.value,nodes:JSON.parse(nodesText.value),arcs:JSON.parse(arcsText.value)});name.value='';await props.refresh()})};</script><template><PageHeading code="02 / NETWORK & NODES" title="先认清节点，也认清每条边。" description="节点ID唯一，平行和反向边可存在但各有独立边ID。图中位置只作布局，不代表地理位置。"/><section class="paper"><div class="section-heading"><h2>模拟中转拓扑</h2><select aria-label="选择网络" :value="ds?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></div><template v-if="ds"><div class="data-caption"><b>{{ds.nodes.length}}节点 / {{arcs.length}}条有向边</b><span>{{ds.source}}</span></div><GraphView :nodes="ds.nodes" :arcs="arcs" id-prefix="dataset"/><div class="table-scroll"><table><thead><tr><th>节点ID</th><th>模拟枢纽</th><th>布局x/y</th></tr></thead><tbody><tr v-for="n in ds.nodes" :key="n.node_id"><td>{{n.node_id}}</td><td>{{n.label}}</td><td>{{n.x.toFixed(1)}} / {{n.y.toFixed(1)}}</td></tr></tbody></table></div></template><Notice v-else>先导入至少两个节点，可同时导入独立ID的有向边，再设置源汇。</Notice></section><section class="paper" v-if="canWrite"><h2>导入模拟网络</h2><form class="grid-form" @submit.prevent="submit"><label>网络名称<input required minlength="2" v-model="name"/></label><label>来源文件名<input v-model="source"/></label><label class="wide">节点JSON<textarea rows="3" required v-model="nodesText"/></label><label class="wide">初始有向边JSON<textarea rows="4" required v-model="arcsText" placeholder='[{"arc_id":"sa","source":"S","target":"A","capacity":3,"travel_minutes":1}, …]'/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">核查并导入网络</button></form></section></template>
